"""Torch port of ego-area classification, DAC and DDC.

Containment is computed exactly on the GPU with an even-odd ray cast per
(point, polygon) pair instead of shapely's STRtree -- at oracle scale
(~10k proposal corners x ~200 polygons x ~100 edges) that is a small batched
tensor op.  Interior points agree with shapely's ``within``; points exactly on
a boundary are the only divergence surface, and those flips are what the
CPU-judge harness measures.

The mask logic below mirrors ``PDMScorer._calculate_ego_area``,
``_calculate_drivable_area_compliance`` and
``_calculate_driving_direction_compliance`` line for line.
"""

from __future__ import annotations

import torch


def points_in_polygons_torch(
    points: torch.Tensor,  # [M, 2]
    edge_starts: torch.Tensor,  # [L, E, 2]
    edge_ends: torch.Tensor,  # [L, E, 2]
) -> torch.Tensor:  # [L, M] bool
    """Even-odd ray cast to +x; interior-point agreement with shapely."""

    px = points[:, 0][None, :, None]  # [1, M, 1]
    py = points[:, 1][None, :, None]
    ax = edge_starts[..., 0][:, None, :]  # [L, 1, E]
    ay = edge_starts[..., 1][:, None, :]
    bx = edge_ends[..., 0][:, None, :]
    by = edge_ends[..., 1][:, None, :]

    straddles = (ay > py) != (by > py)  # [L, M, E]
    denominator = torch.where(
        straddles, by - ay, torch.ones_like(by - ay)
    )
    intersection_x = ax + (py - ay) * (bx - ax) / denominator
    crossings = straddles & (px < intersection_x)
    return crossings.sum(dim=-1) % 2 == 1


def ego_areas_torch(
    corners: torch.Tensor,  # [N, T, 4, 2] FL/RL/RR/FR
    centers: torch.Tensor,  # [N, T, 2]
    edge_starts: torch.Tensor,  # [L, E, 2] all map polygons
    edge_ends: torch.Tensor,  # [L, E, 2]
    drivable_area_indices: torch.Tensor,  # [Ld] long (ROADBLOCK-group polygons)
    lane_indices: torch.Tensor,  # [Ll] long (exact LANE polygons)
    on_route_lane_indices: torch.Tensor,  # [Lr] long
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """(multiple_lanes, non_drivable, oncoming_traffic), each [N, T] bool."""

    n_proposals, n_time = corners.shape[:2]
    corner_points = corners.reshape(-1, 2)
    corner_hits = points_in_polygons_torch(corner_points, edge_starts, edge_ends)
    corner_hits = corner_hits.reshape(-1, n_proposals, n_time, 4)  # [L, N, T, 4]
    corner_hits = corner_hits.permute(1, 2, 0, 3)  # [N, T, L, 4]

    center_hits = points_in_polygons_torch(
        centers.reshape(-1, 2), edge_starts, edge_ends
    )
    center_hits = center_hits.reshape(-1, n_proposals, n_time).permute(1, 2, 0)

    lane_hits = corner_hits[:, :, lane_indices]  # [N, T, Ll, 4]
    multiple_lanes = (lane_hits.sum(dim=-1) > 0).sum(dim=-1) > 1
    not_single_lane = (lane_hits.sum(dim=-1) != 4).all(dim=-1)
    in_multiple_lanes = multiple_lanes & not_single_lane

    drivable_hits = corner_hits[:, :, drivable_area_indices]  # [N, T, Ld, 4]
    corner_covered = drivable_hits.sum(dim=-2) > 0  # [N, T, 4]
    non_drivable = corner_covered.sum(dim=-1) < 4

    oncoming = center_hits[:, :, on_route_lane_indices].sum(dim=-1) == 0

    return in_multiple_lanes, non_drivable, oncoming


def drivable_area_compliance_torch(non_drivable: torch.Tensor) -> torch.Tensor:
    """DAC per proposal: 0.0 the moment any timestep leaves the road."""

    return torch.where(
        non_drivable.any(dim=-1),
        torch.zeros((), dtype=torch.float64, device=non_drivable.device),
        torch.ones((), dtype=torch.float64, device=non_drivable.device),
    )


def driving_direction_compliance_torch(
    centers: torch.Tensor,  # [N, T, 2]
    oncoming_traffic: torch.Tensor,  # [N, T] bool
    interval_length: float,
    horizon_s: float = 1.0,
    compliance_threshold: float = 2.0,
    violation_threshold: float = 6.0,
) -> torch.Tensor:  # [N] in {1.0, 0.5, 0.0}
    """Oncoming progress over a sliding horizon, thresholded like the CPU."""

    # Trailing-axis indexing throughout, so ``centers`` may carry leading batch
    # axes (``[B, N, T, 2]``) and be scored in one call rather than one per
    # window. The arithmetic and the reduction axes are unchanged.
    displacement = torch.zeros(
        centers.shape[:-1], dtype=centers.dtype, device=centers.device
    )
    displacement[..., 1:] = torch.linalg.vector_norm(
        centers[..., 1:, :] - centers[..., :-1, :], dim=-1
    )
    displacement = torch.where(
        oncoming_traffic, displacement, torch.zeros_like(displacement)
    )

    horizon = int(horizon_s / interval_length)
    cumulative = torch.nn.functional.pad(
        torch.cumsum(displacement, dim=-1), (1, 0)
    )  # [N, T+1]
    n_time = displacement.shape[-1]
    windows = []
    for time_idx in range(n_time):
        lo = max(0, time_idx - horizon)
        windows.append(cumulative[..., time_idx + 1] - cumulative[..., lo])
    worst = torch.stack(windows, dim=-1).max(dim=-1).values

    scores = torch.full_like(worst, 0.0, dtype=torch.float64)
    scores = torch.where(
        worst < violation_threshold, torch.full_like(scores, 0.5), scores
    )
    scores = torch.where(
        worst < compliance_threshold, torch.full_like(scores, 1.0), scores
    )
    return scores
